export const meta = {
  "slug": "hugeicons-laptop",
  "family": "hugeicons",
  "name": "laptop",
  "category": "Media",
  "motion": "bounce",
  "component": "createHugeiconsLaptopIcon"
};

export function createHugeiconsLaptopIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
